// Differential test: every corpus script, run through the WebAssembly build,
// must reproduce the transcript the NATIVE build produced (test/golden/*.txt,
// generated by tools/gen-goldens.mjs). Set BOBLOX_CLI=/path/to/boblox_cli to
// additionally diff against a live native run.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { runTranscript } from './transcript.mjs';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const manifest = JSON.parse(readFileSync(here('./corpus/manifest.json'), 'utf8'));

// A readable first-difference report instead of one giant string diff.
function assertSameTranscript(actual, expected, label) {
  if (actual === expected) return;
  const a = actual.split('\n');
  const e = expected.split('\n');
  let i = 0;
  while (i < a.length && i < e.length && a[i] === e[i]) i++;
  assert.fail(
    `${label}: transcripts differ at line ${i + 1}\n` +
    `  expected: ${JSON.stringify(e[i])}\n` +
    `  actual:   ${JSON.stringify(a[i])}\n` +
    `  (${e.length} expected lines vs ${a.length} actual)`,
  );
}

for (const entry of manifest) {
  const name = entry.file.replace(/\.luau$/, '');
  test(`wasm matches native: ${entry.file}`, { timeout: 180_000 }, async () => {
    const source = readFileSync(here(`./corpus/${entry.file}`), 'utf8');
    const got = await runTranscript(source, entry);

    const golden = readFileSync(here(`./golden/${name}.txt`), 'utf8');
    assertSameTranscript(got, golden, 'vs golden');

    if (process.env.BOBLOX_CLI) {
      const args = ['--limit-ms', String(entry.limitMs ?? 10000)];
      if (entry.steps) args.push('--steps', String(entry.steps), '--dt', String(entry.dt ?? 0.1));
      if (entry.tree) args.push('--tree');
      if (entry.props) args.push('--props');
      args.push(here(`./corpus/${entry.file}`));
      const live = spawnSync(process.env.BOBLOX_CLI, args, { encoding: 'utf8', maxBuffer: 1 << 28 });
      assertSameTranscript(got, live.stdout, 'vs live native run');
    }
  });
}
